use crate::local_health_vault::LocalHealthVaultRecord;use crate::local_health_vault_storage::{AuthorizationContext,LocalFileVaultStore,StorageError,VaultAuthorizer,VaultKeyProvider};use crate::longitudinal_observation_repository::{sort_timeline,AuthorizedObservationAccessContext,LongitudinalObservationRepository,ObservationQuery,ObservationRepositoryError,ObservationTimelineEntry};
pub struct LocalLongitudinalObservationRepository<K,A>{vault:LocalFileVaultStore<K,A>}
impl<K,A>LocalLongitudinalObservationRepository<K,A>where K:VaultKeyProvider,A:VaultAuthorizer{pub fn new(vault:LocalFileVaultStore<K,A>)->Self{Self{vault}}fn vault_context(context:&AuthorizedObservationAccessContext)->AuthorizationContext{AuthorizationContext{principal_ref:context.principal_ref().to_owned(),subject_ref:context.subject_ref().to_owned(),scope:context.scope().to_owned()}}fn map_error(error:StorageError)->ObservationRepositoryError{match error{StorageError::AuthorizationDenied=>ObservationRepositoryError::AuthorizationDenied,StorageError::NotFound=>ObservationRepositoryError::NotFound,StorageError::Tombstoned=>ObservationRepositoryError::Tombstoned,StorageError::IndexIntegrityFailure|StorageError::RecordIntegrityFailure=>ObservationRepositoryError::IntegrityFailure,StorageError::InvalidRecord|StorageError::KeyResolutionFailed|StorageError::Io|StorageError::Serialization|StorageError::NonceGenerationFailed=>ObservationRepositoryError::StorageFailure}}fn is_observation(record:&LocalHealthVaultRecord)->bool{record.entity_type=="observation"}}
impl<K,A>LongitudinalObservationRepository for LocalLongitudinalObservationRepository<K,A>where K:VaultKeyProvider,A:VaultAuthorizer{type Observation=LocalHealthVaultRecord;fn put_reference(&self,id:&str,context:&AuthorizedObservationAccessContext)->Result<(),ObservationRepositoryError>{let record=self.vault.get(id,&Self::vault_context(context)).map_err(Self::map_error)?;if !Self::is_observation(&record){return Err(ObservationRepositoryError::InvalidObservation)}Ok(())}fn get(&self,id:&str,context:&AuthorizedObservationAccessContext)->Result<Self::Observation,ObservationRepositoryError>{let record=self.vault.get(id,&Self::vault_context(context)).map_err(Self::map_error)?;if !Self::is_observation(&record){return Err(ObservationRepositoryError::InvalidObservation)}Ok(record)}fn query(&self,context:&AuthorizedObservationAccessContext,query:&ObservationQuery)->Result<Vec<Self::Observation>,ObservationRepositoryError>{let vc=Self::vault_context(context);let entries=self.vault.list(&vc).map_err(Self::map_error)?;let mut observations=Vec::new();for entry in entries{if entry.entity_type!="observation"||query.classification.as_ref().is_some_and(|v|entry.classification!=*v){continue}observations.push(self.vault.get(&entry.record_id,&vc).map_err(Self::map_error)?)}Ok(observations)}fn timeline(&self,context:&AuthorizedObservationAccessContext)->Result<Vec<ObservationTimelineEntry>,ObservationRepositoryError>{let entries=self.vault.list(&Self::vault_context(context)).map_err(Self::map_error)?;let mut timeline=entries.into_iter().filter(|e|e.entity_type=="observation").map(|e|ObservationTimelineEntry{observation_id:e.record_id,subject_ref:e.subject_ref,observed_at:None,recorded_at:e.created_at}).collect::<Vec<_>>();sort_timeline(&mut timeline);Ok(timeline)}fn tombstone(&self,id:&str,context:&AuthorizedObservationAccessContext)->Result<(),ObservationRepositoryError>{self.vault.tombstone(id,&Self::vault_context(context)).map_err(Self::map_error)}fn verify(&self,id:&str,context:&AuthorizedObservationAccessContext)->Result<(),ObservationRepositoryError>{self.vault.verify(id,&Self::vault_context(context)).map_err(Self::map_error)}}
#[cfg(test)]mod tests{use super::*;use crate::canonical_authorization::AuthorizationRequest;#[test]fn delegated_context_preserves_actor_and_subject(){let mut r=AuthorizationRequest{principal_ref:"person-1".into(),subject_ref:"person-1".into(),capability_id:"health.read".into(),resource_type:"health_record".into(),resource_id:"record-1".into(),action:"read".into(),tenant_id:"tenant-1".into(),data_domain:"personal_health".into()};r.principal_ref="clinician-1".into();r.subject_ref="patient-1".into();let c=AuthorizedObservationAccessContext::from_authorized_request(&r).unwrap();assert_eq!(c.principal_ref(),"clinician-1");assert_eq!(c.subject_ref(),"patient-1")}}
